CREATE FUNCTION app.location_json(loc uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('address',address,'lat',latitude,'lng',longitude) FROM directory.locations WHERE id=loc $$;
CREATE FUNCTION app.proof_json(photo uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('url',url,'sha256',sha256,'actorId',actor_id,'lat',latitude,'lng',longitude,'timestamp',to_char(captured_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) FROM evidence.photos WHERE id=photo $$;
CREATE VIEW food.menu_item_payloads AS SELECT m.id,m.event_id,m.position,jsonb_build_object(
 'name',m.name,'ingredients',coalesce((SELECT jsonb_agg(i.name ORDER BY l.position) FROM food.menu_item_ingredients l JOIN food.ingredients i ON i.id=l.ingredient_id WHERE l.menu_item_id=m.id),'[]'),
 'allergens',coalesce((SELECT jsonb_agg(a.name ORDER BY a.id) FROM food.menu_item_allergens l JOIN food.allergens a ON a.id=l.allergen_id WHERE l.menu_item_id=m.id),'[]'),
 'estimatedServings',m.estimated_servings,'handlingRequirement',m.handling,'verified',m.verified,'metadata',m.metadata,'description',m.description) AS payload FROM food.menu_items m;
CREATE VIEW app.domain_payloads AS
SELECT r.id,r.kind,jsonb_build_object('eventId',e.id,'donorId',e.donor_id,'name',e.name,'scheduledAt',e.scheduled_at,'location',app.location_json(e.location_id),'notes',e.notes,'metadata',e.metadata,'items',coalesce((SELECT jsonb_agg(payload ORDER BY position) FROM food.menu_item_payloads WHERE event_id=e.id),'[]')) AS payload FROM food.donor_events e JOIN app.domain_records r ON r.id=e.id
UNION ALL
SELECT r.id,r.kind,jsonb_build_object('centerId',c.id,'ownerId',c.owner_id,'name',c.name,'location',app.location_json(c.location_id),'timeZone',l.timezone,'capabilities',jsonb_build_object('refrigeration',c.refrigeration,'hotHolding',c.hot_holding,'freezer',c.freezer,'maxMealCapacity',c.capacity_servings),'operatingHours',jsonb_build_object('open',to_char(c.open_time,'HH24:MI'),'close',to_char(c.close_time,'HH24:MI')),'seating',c.seating,'staffing',c.staffing,'locationQrCode',c.qr_code,'approved',c.approved,'metadata',c.metadata) FROM directory.partner_centers c JOIN directory.locations l ON l.id=c.location_id JOIN app.domain_records r ON r.id=c.id
UNION ALL
SELECT r.id,r.kind,jsonb_build_object('vehicleId',v.id,'name',v.name,'registration',v.registration,'capacityServings',v.capacity_servings,'status',v.status,'createdAt',r.created_at,'updatedAt',r.updated_at,'metadata',v.metadata,'capabilities',coalesce((SELECT jsonb_agg(handling ORDER BY handling) FROM logistics.vehicle_capabilities WHERE vehicle_id=v.id),'[]'),'equipment',coalesce((SELECT jsonb_agg(e.name ORDER BY e.name) FROM logistics.vehicle_equipment l JOIN logistics.equipment_types e ON e.id=l.equipment_type_id WHERE l.vehicle_id=v.id),'[]')) FROM logistics.vehicles v JOIN app.domain_records r ON r.id=v.id
UNION ALL
SELECT r.id,r.kind,app.proof_json(p.id)||jsonb_build_object('photoId',p.id,'stage',p.stage,'batchId',p.batch_id) FROM evidence.photos p JOIN app.domain_records r ON r.id=p.id
UNION ALL
SELECT r.id,r.kind,jsonb_strip_nulls(jsonb_build_object('batchId',b.id,'donorId',b.donor_id,'donorEventId',b.event_id,'eventName',e.name,'location',app.location_json(b.location_id),'status',b.status,'handlingRequirement',b.handling,'expiresAt',b.expires_at,'createdAt',r.created_at,'rejectionReason',b.rejection_reason,'metadata',b.metadata))||jsonb_build_object('qrStickerId',b.sticker_id,'centerId',b.center_id,'driverId',b.driver_id,'chainOfCustody',jsonb_build_object('stage1_DonorPic',app.proof_json(b.donor_photo_id),'stage2_PickupPic',app.proof_json(b.pickup_photo_id),'stage3_DropoffPic',app.proof_json(b.dropoff_photo_id)),'items',coalesce((SELECT jsonb_agg(m.payload||jsonb_build_object('estimatedServings',i.servings) ORDER BY m.position) FROM food.batch_items i JOIN food.menu_item_payloads m ON m.id=i.menu_item_id WHERE i.batch_id=b.id),'[]')) FROM food.food_batches b JOIN food.donor_events e ON e.id=b.event_id JOIN app.domain_records r ON r.id=b.id
UNION ALL
SELECT r.id,r.kind,jsonb_strip_nulls(jsonb_build_object('routeId',t.id,'driverId',t.driver_id,'vehicleId',t.vehicle_id,'vehicleSnapshot',t.vehicle_snapshot,'cancelledAt',t.cancelled_at,'cancellationReason',t.cancellation_reason,'centerId',t.center_id,'status',t.status,'distanceMiles',t.distance_miles,'estimatedMinutes',t.estimated_minutes,'createdAt',r.created_at,'metadata',t.metadata,'assignedBatches',coalesce((SELECT jsonb_agg(batch_id ORDER BY batch_id) FROM logistics.route_batches WHERE route_id=t.id),'[]'),'waypoints',coalesce((SELECT jsonb_agg(jsonb_build_object('type',s.stop_type,'status',s.status,'batchId',s.batch_id,'location',app.location_json(s.location_id)) ORDER BY s.position) FROM logistics.route_stops s WHERE s.route_id=t.id),'[]'))) FROM logistics.routes t JOIN app.domain_records r ON r.id=t.id
UNION ALL
SELECT r.id,r.kind,jsonb_build_object('scanId',s.id,'batchId',s.batch_id,'actorId',s.actor_id,'kind',s.event_type,'value',s.scanned_value,'lat',s.latitude,'lng',s.longitude,'timestamp',s.occurred_at) FROM evidence.custody_events s JOIN app.domain_records r ON r.id=s.id
UNION ALL
SELECT r.id,r.kind,jsonb_build_object('driverId',d.driver_id,'lat',d.latitude,'lng',d.longitude,'timestamp',d.reported_at,'source',d.source) FROM evidence.location_reports d JOIN app.domain_records r ON r.id=d.id
UNION ALL
SELECT r.id,r.kind,jsonb_build_object('reviewId',f.id,'authorId',f.author_id,'targetType',f.target_type,'targetId',f.target_id,'linkedBatchId',f.batch_id,'sentiment',f.sentiment,'rawText',f.raw_text,'aiParsedFlags',f.parsed_flags,'analysisMode',f.analysis_mode,'createdAt',r.created_at,'metadata',f.metadata) FROM feedback.reviews f JOIN app.domain_records r ON r.id=f.id;
